\set ON_ERROR_STOP on
\copy (SELECT sc.sense_id, sc.lexeme_id, sc.lemma, sc.pos, src.code AS source, src.version AS source_version, sc.sense_no, coalesce(sc.definition, sc.gloss_en, '') AS definition, se.definition AS raw_definition, to_json(coalesce(sc.gloss_en_context, ARRAY[]::text[]))::text AS gloss_context, sc.register, sc.domain, coalesce(se.attributes->'tags','[]'::jsonb)::text AS tags, coalesce(se.attributes->'topics','[]'::jsonb)::text AS topics, sc.frequency_rank FROM core.lexeme le JOIN core.sense se ON se.lexeme_id = le.id JOIN serve.sense_card sc ON sc.sense_id = se.id JOIN public.source src ON src.id = se.source_id JOIN staging.tmp_v2_words w ON w.lemma = le.lemma WHERE le.language_id = 1 ORDER BY le.lemma, src.code, sc.lexeme_id, sc.sense_no, sc.sense_id) TO '/tmp/new-senses.csv' WITH (FORMAT csv)
